// REGENERATED from real NCRB (National Crime Records Bureau) district-year
// data — replaces the previous hand-authored demo dataset.
//
// Source data : ncrb_district_year_features.csv (district x year engineered
//               features: IPC / SLL / crimes-against-women / crimes-against-
//               -children / cyber-crime counts, state-percentile ranks,
//               year-over-year growth, and a composite 0-1 "severity" score)
// Geocoding   : matched against Vynex/indian-cities-geodata (public dataset,
//               itself sourced from Census/Google Maps) — 445 of 1,326
//               reported districts had a matchable city and got REAL lat/lon.
//               Districts without a match are intentionally omitted here
//               rather than given an invented coordinate — see
//               /ml-pipeline/state_summary_real.json for full 39-state
//               coverage that does not depend on geocoding.
// Population  : Census 2011 district population (public dataset), used only
//               where a district could be matched.
// "risk_score": the real `severity` composite from the source data (0-100).
// "predicted_next_year_*": output of a GradientBoostingRegressor trained on
//               a true temporal holdout (train <=2022, test 2023-2024).
//               Holdout R²=0.8855, risk-class accuracy=0.7768.
//               Honesty note: a naive "next year = this year" baseline
//               scores R²=0.9288 / accuracy=0.8253
//               on the same holdout — i.e. risk is highly persistent
//               year-over-year and the model does not decisively beat that
//               baseline. Full methodology: /ml-pipeline/README.md
// Regenerate  : python3 ml-pipeline/01_build_master.py && 02_train_model.py && 03_export_hotspots.py

export interface V5HotspotRaw {
  id: string
  city: string
  state: string
  lat: number
  lon: number
  risk_level: string
  risk_score: number
  model_confidence: number
  crime_rate_per_lakh: number | null
  predicted_crimes: string[]
  primary_warning: string
  trend: string
  population_lakh: number | null
  radius_meters: number
  total_crimes_reported: number
  data_year: number
  geo_source: string
  predicted_next_year_severity: number
  predicted_next_year_risk_level: string
  features_v5?: Record<string, any>
}

export const RISK_COLORS: Record<string, string> = {
  critical: '#ef4444',
  high:     '#f97316',
  medium:   '#eab308',
  low:      '#22c55e',
}

export const RISK_BG: Record<string, string> = {
  critical: 'bg-red-50 text-red-600 border-red-100',
  high:     'bg-orange-50 text-orange-600 border-orange-100',
  medium:   'bg-yellow-50 text-yellow-600 border-yellow-100',
  low:      'bg-green-50 text-green-600 border-green-100',
}

